from builtins import filter, str, object
import re
from robot.libraries.BuiltIn import BuiltIn
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.utils.string_format import encode_str

logger = BackgroundLogger.Instance()


class ExecuteAndVerify(object):
    def __init__(self):
        pass

    def execute_commands_and_verify(self):
        """
        Performs command execution and validation.
        Returns:

        """
        result = {}
        commands_list = self.command_profile
        logger.info("commands_list is {}".format(commands_list))
        for command in commands_list:
            try:
                logger.debug("command:{}".format(command))
                result = self._execute_switch_cmd_and_get_output(command)
                self._validate_output_of_command(result)
                self._verify_if_output_has_error_messages(result)
            except Exception as e:
                self._execute_show_conf_command(self.enable_prompt, dump_time="fail")
                self.close_connection()
                raise e
        else:
            logger.info("PASS :: Command result verification passed")

    def _get_command_based_on_instance(self, command):
        call_function_for_get_command = {True: self._get_command_from_dict,
                                         False: self._ret_command}
        return call_function_for_get_command.get(isinstance(command, dict))(command)

    def _get_command_from_dict(self, command):
        return list(command.keys())[0]

    def _get_expected_result_from_dict(self, command):
        return list(command.values())[0]

    def _ret_none(self, command):
        return None

    def _ret_command(self, command):
        return command

    def _execute_cmd(self, command):
        pass

    def _execute_switch_cmd_and_get_output(self, command):
        """
        Executes command on switch. And returns the dictionary in the format
        'coammnd_dict{"expected_result": expected_output,
         "obtained_result": output,'command':command}'
        Args:
            command

        Returns:
            command_dict
        """
        command_dict = {}
        call_function_for_get_value = {True: self._get_expected_result_from_dict, False: self._ret_none}
        command_dict['command'] = self._get_command_based_on_instance(command)
        command_dict['expected_result'] = call_function_for_get_value.get(isinstance(command, dict))(command)
        command_dict['obtained_result'] = self._execute_cmd(command_dict['command'])
        # command_dict['obtained_result'] = self._execute_cmd(encode_str(command_dict['command']))
        logger.info("Command :: {0}\nExpected Result :: {1}\nObtained Result ::\n{2}".format(command_dict['command'],
                                                                                             command_dict[
                                                                                                 "expected_result"],
                                                                                             command_dict[
                                                                                                 "obtained_result"]))

        return command_dict

    def _validate_output_of_command(self, command_dict):
        """
        Validates output of command.
        Args:
            command_dict:

        Returns:

        """
        if command_dict["expected_result"] is not None and command_dict["expected_result"] != '':
            logger.debug("Verifying output exp = {} actual = {}".format(command_dict["expected_result"],
                                                                        command_dict["obtained_result"]))
            if bool(re.search(command_dict["expected_result"], command_dict["obtained_result"], re.DOTALL)):
                command_dict['status'] = "PASS"
            else:
                BuiltIn().fail(
                    "{0} :: Command verification failed\nExpected result::{1}\nObtained result::{2}".format(
                        command_dict["command"],
                        command_dict["expected_result"],
                        command_dict["obtained_result"]))

    def _execute_show_conf_command(self, prompt, dump_time='start'):
        logger.info("Show command not implemented!!!")

    def _verify_if_output_has_error_messages(self, command_dict):
        """
         Checks if error messages are present in the output of command.
        Args:
            output:
            command:

        Returns:

        """
        result = list(filter((lambda msg: msg in command_dict['obtained_result']), self.error_messages))
        if len(result):
            logger.info(result)
            BuiltIn().fail("FAIL :: {0} : {1}".format(command_dict['command'], str(result)))
